import random
import math
from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_boolean_function(n):
        return [random.choice([0, 1]) for _ in range(2**n)]

    def and_or_tree(f, n):
        if n == 1:
            return f[0]
        else:
            mid = 2**(n-1)
            left = and_or_tree(f[:mid], n-1)
            right = and_or_tree(f[mid:], n-1)
            return [left[i] & right[i] for i in range(mid)] + [left[i] | right[i] for i in range(mid)]

    def communication_complexity(tree):
        if isinstance(tree, list):
            return 2 * communication_complexity(tree[0])
        else:
            return 1

    def weil_representation(f):
        n = len(f)
        W = [[Fraction(0) for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if f[i] == f[j]:
                    W[i][j] = Fraction(1)
                else:
                    W[i][j] = Fraction(-1)
        return W

    def min_rank(W):
        n = len(W)
        rank = 0
        for i in range(n):
            pivot_row = -1
            for j in range(i, n):
                if W[j][i] != 0:
                    pivot_row = j
                    break
            if pivot_row == -1:
                continue
            rank += 1
            for j in range(n):
                W[i][j], W[pivot_row][j] = W[pivot_row][j], W[i][j]
            for j in range(i + 1, n):
                factor = W[j][i] / W[i][i]
                for k in range(n):
                    W[j][k] -= factor * W[i][k]
        return rank

    def compute_metric(f):
        n = len(f)
        tree = and_or_tree(f, int(math.log2(n)))
        cc = communication_complexity(tree)
        W = weil_representation(f)
        rho_f = min_rank(W)
        return cc <= 2**rho_f

    instances_tested = 0
    total_metric_value = 0
    conjecture_holds = True
    counterexample = ""

    for _ in range(30):
        n = random.choice([5, 10, 15, 20, 30, 40])
        f = generate_boolean_function(n)
        instances_tested += 1
        if not compute_metric(f):
            conjecture_holds = False
            counterexample = "Communication complexity exceeds 2^ρ(f)"

    return {
        "metric_name": "communication_complexity",
        "metric_value": total_metric_value / instances_tested,
        "instances_tested": instances_tested,
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [2**i + 7 for i in range(5, 30)]

    results = []
    for seed in seeds:
